const r = await tools.exec_command({cmd:"python3 - <<'PY'
import pathlib,re,collections
files=list(pathlib.Path('.').rglob('*.go'))
# declarations incl methods, package funcs; names
D=[]
pat=re.compile(r'^\s*func\s+(?:\([^)]*\)\s*)?(\w+)\s*\(',re.M)
for p in files:
 s=p.read_text(errors='ignore')
 for m in pat.finditer(s): D.append((m.group(1),p,m.start()))
alltext='\n'.join(p.read_text(errors='ignore') for p in files)
for name,p,pos in sorted(D,key=lambda x:-len(re.findall(r'\b'+re.escape(x[0])+r'\s*\(',alltext))):
 n=len(re.findall(r'\b'+re.escape(name)+r'\s*\(',alltext))-1
 if str(p).startswith('internal/') and n>=3:
  # distinct caller funcs approximately lines containing invocation
  callers=[]
  for q in files:
   txt=q.read_text(errors='ignore')
   for i,line in enumerate(txt.splitlines(),1):
    if re.search(r'\b'+re.escape(name)+r'\s*\(',line): callers.append(f'{q}:{i}')
  print(f'{n:3} {name:35} {p} refs={len(callers)}')
PY","workdir":"/bench/repo","yield_time_ms":10000,"max_output_tokens":12000}); text(r.output);

